package relayproof

import (
	"bytes"
	"errors"
	"testing"
)

func TestScratchCasingScenarios(t *testing.T) {
	ff := string([]byte{0xFF})

	type tc struct {
		name string
		body string
		// wantErr: "" = accept and wantPayload; "both"; "b64"
		wantErr     string
		wantPayload string
	}
	cases := []tc{
		{"uppercase plain", `{"t":"submit","seq":0,"id":"m","from":"a","to":"b","nonce":1,"proofAt":10,"PAYLOAD":"hi"}`, "", "hi"},
		{"mixed plain", `{"t":"submit","seq":0,"id":"m","from":"a","to":"b","nonce":1,"proofAt":10,"Payload":"hi"}`, "", "hi"},
		{"uppercase b64", `{"t":"submit","seq":0,"id":"m","from":"a","to":"b","nonce":1,"proofAt":10,"PAYLOADB64":"/w=="}`, "", ff},
		{"mixed b64", `{"t":"submit","seq":0,"id":"m","from":"a","to":"b","nonce":1,"proofAt":10,"PayloadB64":"/w=="}`, "", ff},
		{"lower b64 baseline", `{"t":"submit","seq":0,"id":"m","from":"a","to":"b","nonce":1,"proofAt":10,"payloadB64":"/w=="}`, "", ff},
		{"upper plain empty + lower b64", `{"t":"submit","seq":0,"id":"m","from":"a","to":"b","nonce":1,"proofAt":10,"PAYLOAD":"","payloadB64":"/w=="}`, "both", ""},
		{"lower plain + upper b64 empty", `{"t":"submit","seq":0,"id":"m","from":"a","to":"b","nonce":1,"proofAt":10,"payload":"x","PAYLOADB64":""}`, "both", ""},
		{"both upper, both empty", `{"t":"submit","seq":0,"id":"m","from":"a","to":"b","nonce":1,"proofAt":10,"PAYLOAD":"","PAYLOADB64":""}`, "both", ""},
		{"both mixed, same bytes", `{"t":"submit","seq":0,"id":"m","from":"a","to":"b","nonce":1,"proofAt":10,"Payload":"x","PAYLOADB64":"eA=="}`, "both", ""},
		{"undecodable upper b64", `{"t":"submit","seq":0,"id":"m","from":"a","to":"b","nonce":1,"proofAt":10,"PAYLOADB64":"!!!bad!!!"}`, "b64", ""},
		{"legal empty: neither", `{"t":"submit","seq":0,"id":"m","from":"a","to":"b","nonce":1,"proofAt":10}`, "", ""},
		{"legal empty: upper plain empty", `{"t":"submit","seq":0,"id":"m","from":"a","to":"b","nonce":1,"proofAt":10,"PAYLOAD":""}`, "", ""},
		{"legal empty: upper b64 empty", `{"t":"submit","seq":0,"id":"m","from":"a","to":"b","nonce":1,"proofAt":10,"PAYLOADB64":""}`, "", ""},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			dir := t.TempDir()
			var raw []byte
			raw = append(raw, logMagic...)
			raw = append(raw, encodeFrame(mustMarshal(&logEntry{T: kindVersion, V: currentLogV}))...)
			raw = append(raw, encodeFrame([]byte(c.body))...)
			writeRawLog(t, dir, raw)

			q, err := Open(dir)
			if c.wantErr == "" {
				if err != nil {
					t.Fatalf("expected accept, got %v", err)
				}
				defer q.Close()
				got, ok := q.Query("m")
				if !ok {
					t.Fatal("message missing")
				}
				if !bytes.Equal([]byte(got.Payload), []byte(c.wantPayload)) {
					t.Fatalf("payload = % x want % x", got.Payload, c.wantPayload)
				}
				// byte-identical resubmit idempotent; one-byte change conflicts
				same := payloadEnvelope("m", 1, c.wantPayload)
				same.Message.ProofAt = 10
				if echo, err := q.Submit(same); err != nil || echo.Msg.Message.Payload != c.wantPayload {
					t.Fatalf("identical resubmit: echo=%x err=%v", echo.Msg.Message.Payload, err)
				}
				if c.wantPayload != "" || true {
					diff := same
					diff.Message.Payload = c.wantPayload + "z"
					if _, err := q.Submit(diff); !errors.Is(err, ErrConflict) {
						t.Fatalf("changed payload must conflict: %v", err)
					}
				}
			} else {
				assertCorruptAndUntouched(t, dir, raw)
				// reopen to check error wording distinguishes the two verdicts
				q2, err2 := Open(dir)
				if q2 != nil {
					q2.Close()
				}
				if err2 == nil {
					t.Fatal("second open unexpectedly succeeded")
				}
				if c.wantErr == "both" && !contains(err2.Error(), "both payload and payloadB64") {
					t.Fatalf("want representation-conflict wording, got %v", err2)
				}
				if c.wantErr == "b64" && !contains(err2.Error(), "undecodable payloadB64") {
					t.Fatalf("want undecodable wording, got %v", err2)
				}
			}
		})
	}
}

func contains(s, sub string) bool {
	return bytes.Contains([]byte(s), []byte(sub))
}

