	t.Run("to cased dual rejected", func(t *testing.T) {
		dir := t.TempDir()
		var raw []byte
		raw = append(raw, logMagic...)
		raw = append(raw, encodeFrame(mustMarshal(&logEntry{T: kindVersion, V: currentLogV}))...)
		raw = append(raw, encodeFrame([]byte(
			`{"t":"submit","seq":0,"id":"m","from":"a","nonce":1,"proofAt":10,"TO":"","TOB64":"/w=="}`))...)
		writeRawLog(t, dir, raw)
		assertCorruptAndUntouched(t, dir, raw)
	})

	// id/reason remain value-based: uppercase ID with idB64 still clashes by value.
	t.Run("id uppercase with idB64 clashes by value", func(t *testing.T) {
		dir := t.TempDir()
		var raw []byte
		raw = append(raw, logMagic...)
		raw = append(raw, encodeFrame(mustMarshal(&logEntry{T: kindVersion, V: currentLogV}))...)
		raw = append(raw, encodeFrame([]byte(
			`{"t":"submit","seq":0,"from":"a","to":"b","nonce":1,"proofAt":10,"ID":"x","idB64":"eA=="}`))...)
